        const updateTree = (nodes: TreeNodeData[]): TreeNodeData[] => {
            return nodes.map(node => {
                if (node.id === id) {
                    return { ...node, expanded: !node.expanded };
                }
                if (node.children) {
                    return {
                        ...node,
                        children: updateTree(node.children),
                    };
                }
                return node;
            });
        };

